const Indeterminate = () => {
    const [ fruits, setFruits ] = useState( {
        apple: false,
        orange: false,
    } );

    const isAllChecked = Object.values( fruits ).every( Boolean );
    const isIndeterminate =
        Object.values( fruits ).some( Boolean ) && ! isAllChecked;

    return (
        <VStack>
            <CheckboxControl
                label="Select all"
                checked={ isAllChecked }
                indeterminate={ isIndeterminate }
                onChange={ ( v ) => {
                    setFruits( {
                        apple: v,
                        orange: v,
                    } );
                    onChange( v );
                } } />
            <CheckboxControl
                label="Apple"
                checked={ fruits.apple }
                onChange={ ( apple ) =>
                    setFruits( ( prevState ) => ( {
                        ...prevState,
                        apple,
                    } ) )
                } />
            <CheckboxControl
                label="Orange"
                checked={ fruits.orange }
                onChange={ ( orange ) =>
                    setFruits( ( prevState ) => ( {
                        ...prevState,
                        orange,
                    } ) )
                } />
        </VStack>
    );
};

const WithCustomLabel = () => {
